import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 8 章：在安全边界内让 Agent 行动","description":"只读/写入/执行/外部操作四级权限、逐步开放、敏感操作人工确认、备份与可撤销性；产出个人权限分级表。","frontmatter":{"title":"第 8 章：在安全边界内让 Agent 行动","description":"只读/写入/执行/外部操作四级权限、逐步开放、敏感操作人工确认、备份与可撤销性；产出个人权限分级表。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/08-safe-boundaries.md","filePath":"guide/08-safe-boundaries.md","lastUpdated":null}'),o={name:"guide/08-safe-boundaries.md"};function n(i,t,l,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="第-8-章-在安全边界内让-agent-行动" tabindex="-1">第 8 章：在安全边界内让 Agent 行动 <a class="header-anchor" href="#第-8-章-在安全边界内让-agent-行动" aria-label="Permalink to &quot;第 8 章：在安全边界内让 Agent 行动&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>前几章让你敢用 Agent 了，这一章教你怎么<strong>安全地</strong>用。权限是 Agent 使用里最容易被新手忽略、后果却最严重的环节——你以为它只会「读」，它可能「写」；你以为「没弹窗」就是「没动作」，实测证明完全不是。本章产出<strong>个人权限分级表</strong>，并解释一个反直觉的事实：<strong>没有权限弹窗 ≠ 没有越权行为</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>第 5 章实测里，两款产品在任务明确写着「只读 <code>input</code>」的情况下，<strong>没有弹出任何权限确认，就读取了工作区其他文件</strong>（Qoder、Hermes 页有记录）。另一款产品把文件写进了禁止目录，之后自己恢复（Hermes）。</p><p>对新手来说，最危险的错觉是：「它没问我，说明它没乱来。」<strong>真相是：权限机制和权限行为是两回事</strong>——产品可能默认就允许读取整个工作区，也可能在你没注意时执行了操作。所以你的安全策略不能是「信任弹窗」，而必须是「<strong>从最小权限开始，自己控制边界</strong>」。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>四级权限，逐级开放</strong>：只读 → 写入 → 执行 → 外部操作。新手一律从「只读」开始，需要时再升一级；</li><li><strong>逐步开放原则</strong>：先在一个临时目录/低风险任务里验证，再对真实文件开放；</li><li><strong>五类动作必须人工确认</strong>：发送、发布、付款、删除、提供敏感信息——这些不做成自动步骤；</li><li><strong>备份与可撤销性</strong>：让 Agent 动重要文件前，先备份；输出到独立目录，保证「删错了能恢复」；</li><li><strong>权限的最终责任在人</strong>：授权是你给的，后果你承担（第 3 章）。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>只读（Read-only）</strong>：能看、能读，不能改。新手最安全的起点。</li><li><strong>写入（Write）</strong>：能创建/修改文件。只对允许的目录开放。</li><li><strong>执行（Execute）</strong>：能运行命令/脚本。影响面大，默认关闭。</li><li><strong>外部操作（External）</strong>：联网、发送消息、调用外部服务、付款等。影响不可逆，最高风险。</li><li><strong>可撤销性（Reversibility）</strong>：出事后能否恢复原状。白话解释：有没有后悔药。备份、版本记录、独立输出目录都能提供后悔药。</li><li><strong>最小权限（Least Privilege）</strong>：只给完成当前任务所需的最小权限。白话解释：让实习生只碰他该碰的抽屉。</li></ul><h2 id="权限分级表" tabindex="-1">权限分级表 <a class="header-anchor" href="#权限分级表" aria-label="Permalink to &quot;权限分级表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>允许什么</th><th>典型操作</th><th>风险</th><th>新手建议</th></tr></thead><tbody><tr><td><strong>L0 只读</strong></td><td>读取、分析、总结</td><td>读文件、查资料、生成建议</td><td>低</td><td>从这级开始</td></tr><tr><td><strong>L1 写入（限定目录）</strong></td><td>在指定目录创建/修改文件</td><td>输出文档、整理素材</td><td>中</td><td>输出到独立 <code>output/</code></td></tr><tr><td><strong>L2 执行</strong></td><td>运行命令/脚本</td><td>批量重命名、跑脚本、装依赖</td><td>高</td><td>默认关闭，看清单再批</td></tr><tr><td><strong>L3 外部操作</strong></td><td>联网、发送、发布、付款</td><td>发邮件、发帖、下单、删远程</td><td>极高</td><td>永远人工确认</td></tr></tbody></table><p><strong>你的「个人权限分级表」</strong>：为序章任务的每个环节标级别，并写明每一级「允许/禁止」的具体清单。对照第 3 章分工表的「人工确认点」。</p><h2 id="跟着做-给你的任务上「权限锁」" tabindex="-1">跟着做：给你的任务上「权限锁」 <a class="header-anchor" href="#跟着做-给你的任务上「权限锁」" aria-label="Permalink to &quot;跟着做：给你的任务上「权限锁」&quot;">​</a></h2><h3 id="第一步-建独立工作目录" tabindex="-1">第一步：建独立工作目录 <a class="header-anchor" href="#第一步-建独立工作目录" aria-label="Permalink to &quot;第一步：建独立工作目录&quot;">​</a></h3><p>为每个任务建独立目录：<code>任务名/input/</code>（只读材料）、<code>任务名/output/</code>（Agent 输出）、<code>任务名/backup/</code>（原文件备份）。<strong>让 Agent 只在这三个目录里活动。</strong></p><h3 id="第二步-从-l0-开始" tabindex="-1">第二步：从 L0 开始 <a class="header-anchor" href="#第二步-从-l0-开始" aria-label="Permalink to &quot;第二步：从 L0 开始&quot;">​</a></h3><p>第一次跑任务时，只给只读权限：让 Agent 先「读材料、出计划」，你把计划看完，再决定是否升级。</p><h3 id="第三步-逐级升级-每次只升一级" tabindex="-1">第三步：逐级升级，每次只升一级 <a class="header-anchor" href="#第三步-逐级升级-每次只升一级" aria-label="Permalink to &quot;第三步：逐级升级，每次只升一级&quot;">​</a></h3><p>计划没问题 → 升 L1（输出到 <code>output/</code>）→ 需要运行脚本 → 升 L2（先看清单）→ 需要联网/发送 → L3 人工做，或每步确认。</p><h3 id="第四步-写「权限卡」" tabindex="-1">第四步：写「权限卡」 <a class="header-anchor" href="#第四步-写「权限卡」" aria-label="Permalink to &quot;第四步：写「权限卡」&quot;">​</a></h3><p>在任务卡约束字段基础上，加一张权限卡：</p><table tabindex="0"><thead><tr><th>权限项</th><th>允许</th><th>禁止</th></tr></thead><tbody><tr><td>读取</td><td><code>input/</code>、<code>材料/</code></td><td>其他一切目录</td></tr><tr><td>写入</td><td><code>output/</code></td><td>原文件、<code>input/</code></td></tr><tr><td>执行</td><td>无（或列出白名单脚本）</td><td>一切未列出的命令</td></tr><tr><td>外部</td><td>无</td><td>联网、发送、发布、付款</td></tr></tbody></table><h3 id="第五步-验收时检查「它到底碰了什么」" tabindex="-1">第五步：验收时检查「它到底碰了什么」 <a class="header-anchor" href="#第五步-验收时检查「它到底碰了什么」" aria-label="Permalink to &quot;第五步：验收时检查「它到底碰了什么」&quot;">​</a></h3><p>交付后，用产品的变更/历史视图（第 5 章各产品页讲了怎么看）检查：读过的文件清单、写过的文件清单、运行过的操作。<strong>第 6 章选择表里的「边界」维度分数，就是各产品在这一步表现的评价。</strong></p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>以第 5 章统一基准任务的安全设计为例：</p><ul><li>目录：<code>runs/2026-08-12-产品名/</code> 下分 <code>input/</code>、<code>output/</code>、<code>run-record.md</code>；</li><li>权限卡：读取=仅 <code>input/</code>；写入=仅 <code>output/</code>；执行=无；外部=无联网；</li><li>基线：任务开始前对 <code>input/</code> 7 份文件记录 SHA-256 哈希（文件指纹），结束后复核「7/7 一致」——这是「可撤销性」的自动检查；</li><li>实测结果：多数产品 7/7 一致；Qoder/Hermes 存在读取越界但<strong>没有改任何输入文件</strong>；Hermes 误写 <code>input/output/</code> 后自动恢复且哈希仍 7/7——<strong>最终状态正确，但过程违规</strong>，验收记录里两者分开标注。</li></ul><p>这个例子教你：<strong>「结果没坏」不等于「过程合规」；权限检查要看过程（读了什么、写了哪），而不只看结果。</strong></p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>「它没弹窗，应该没乱来」</td><td>误以为弹窗=边界</td><td>验收时检查实际读/写记录（第 10 章）</td></tr><tr><td>Agent 改了原文件</td><td>给了整个目录写入权</td><td>只给 <code>output/</code> 写入；原文件先备份</td></tr><tr><td>跑了奇怪命令</td><td>开了 L2 未看清单</td><td>默认关执行，白名单制</td></tr><tr><td>联网乱搜或发了消息</td><td>外部操作没锁</td><td>外部一律人工确认</td></tr><tr><td>想撤销改错了的文件</td><td>没备份</td><td>动手前备份到 <code>backup/</code>；输出用独立目录</td></tr><tr><td>权限弹窗看不太懂就点了允许</td><td>文案不清/赶时间</td><td>看不懂就拒绝，先查文档再决定</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>涉及<strong>删除、覆盖、格式化</strong>：无论 Agent 多「自信」，先备份再让它碰；</li><li>涉及<strong>支付、发送、发布</strong>：永远人工执行最后一步，即使内容 90% 是 Agent 生成的；</li><li>涉及<strong>公司数据、他人隐私</strong>：遵守组织政策，确认授权；</li><li>看到不认识的权限弹窗：<strong>先拒绝</strong>，查清楚再授权；拒绝的成本远低于误授权的成本。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>25 分钟：为序章任务建目录结构（input/output/backup）、写权限卡（四级允许/禁止清单）、对关键文件做一次备份。如果你已经在用某款产品，找到它的「权限/审批设置」入口，把默认调成最低档。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人权限分级表</strong>（L0–L3 + 允许/禁止清单）+ 任务目录结构 + 备份。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>四级权限：只读 → 写入 → 执行 → 外部操作，逐级开放；</li><li>没有弹窗 ≠ 没有越权，验收要看实际读写记录；</li><li>五类动作（发送/发布/付款/删除/敏感信息）永远人工确认；</li><li>备份与独立输出目录提供可撤销性；</li><li>授权在人，后果在人——从最小权限开始。</li></ol>',39)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
